(function(root){'use strict';
const core=root.KANA_ENDGAME_CORE,records=root.KANA_DATA.repositories.records,repos=root.KANA_DATA.repositories;let stats=records.getEndgames(core.emptyStats()),run=null,timer=null,deadline=0,current=null,previous='',turn=0,streak=0,hits=0,errors=0,questionAt=0,normalStarter=null,syncTimer=null,pool=[];
function save(){records.saveEndgames(stats);clearTimeout(syncTimer);syncTimer=setTimeout(()=>root.KANA_CLOUD.sync.enqueueSnapshot('endgames',stats),350);}
function localDateKey(){const d=new Date(),p=n=>String(n).padStart(2,'0');return `${d.getFullYear()}-${p(d.getMonth()+1)}-${p(d.getDate())}`;}
function deviceId(){return repos.store.read(root.KANA_PERSISTENCE.STATE_KEY,{identity:{guestId:'device'}}).identity.guestId;}
function cloudAttempt(mode,item,correct,responseMs){root.KANA_CLOUD.sync.enqueueAttempt({sessionId:run?.sessionId,item:{id:`${mode}:${item.id||item[0]}`,written:item.written||item[0],reading:item.reading||'',category:mode},mode,correct,responseMs,stat:null,meta:{requiresPortuguese:mode!=='blitz'}});}
function cloudSession(status='active',extra={}){if(!run?.sessionId)return;root.KANA_CLOUD.sync.enqueueSession({id:run.sessionId,deviceId:deviceId(),mode:run.mode,territory:run.territory,startedAt:new Date(run.startedAt).toISOString(),endedAt:status==='completed'?new Date().toISOString():null,status,summary:{hits,errors,attempts:hits+errors,dateKey:localDateKey(),excludeFromDaily:true,endgame:true,...extra}});}
function el(tag,className,text){const node=document.createElement(tag);if(className)node.className=className;if(text!=null)node.textContent=text;return node;}
const screen=el('section','screen territory-screen');screen.id='territoryScreen';screen.hidden=true;screen.innerHTML='<p class="eyebrow" id="territoryEyebrow"></p><h1 id="territoryTitle"></h1><p class="intro" id="territoryIntro"></p><div class="level-list" id="territoryCards"></div>';
const challenge=el('section','screen challenge-screen');challenge.id='challengeScreen';challenge.hidden=true;challenge.innerHTML='<div id="challengeIntro"><p class="eyebrow" id="challengeEyebrow"></p><h1 class="challenge-title" id="challengeTitle"></h1><p class="intro" id="challengeCopy"></p><div class="challenge-record" id="challengeRecord"></div><button class="challenge-start" id="challengeStart" type="button">INICIAR</button></div><div id="challengePlay" hidden><div class="challenge-head"><span id="challengeMode"></span><span id="challengeSignal"></span></div><div class="timer-track" id="timerTrack"><i id="timerFill"></i></div><div class="challenge-glyph" id="challengeGlyph"></div><p class="challenge-prompt" id="challengePrompt"></p><form id="challengeForm"><input id="challengeAnswer" autocomplete="off" autocapitalize="off" spellcheck="false"><button class="submit" type="submit">confirmar</button></form><div class="choices" id="challengeChoices" hidden></div><p class="feedback" id="challengeFeedback"></p></div><div id="challengeResult" hidden><p class="eyebrow" id="resultEyebrow"></p><span class="challenge-number" id="resultNumber"></span><h1 id="resultTitle"></h1><p class="intro" id="resultCopy"></p><button class="challenge-start" id="challengeRetry" type="button">TENTAR NOVAMENTE</button></div>';
document.querySelector('main').append(screen,challenge);const $=id=>document.getElementById(id),home=$('home'),levels=$('vocabularyLevels'),game=$('game'),reference=$('reference'),study=$('studyLink'),back=$('back');
const configs={hiragana:{title:'Hiragana',intro:'Reconheça com calma. Depois prove que já não precisa pensar.',normal:'Treino de Hiragana',normalCopy:'O treino clássico continua exatamente como antes.',end:'BLITZ',endCopy:'Automaticidade sob pressão. O tempo diminui enquanto você avança.'},katakana:{title:'Katakana',intro:'Aprenda os símbolos. Depois decifre o que o japonês fez com o estrangeiro.',normal:'Treino de Katakana',normalCopy:'Símbolo por símbolo, no seu ritmo.',end:'ALIEN',endCopy:'Empréstimos, abreviações e adaptações cada vez menos óbvias.'},kanji:{title:'Kanji',intro:'Reconheça as partes antes de enfrentar os monstros que elas formam.',normal:'Treino de Kanji',normalCopy:'Leitura e significado dos kanji já existentes.',end:'CHIMERA',endCopy:'Inferência de compostos reais a partir de componentes conhecidos.'}};
function hideAll(){home.hidden=true;levels.hidden=true;game.hidden=true;reference.hidden=true;screen.hidden=true;challenge.hidden=true;study.hidden=true;back.hidden=false;}
function openTerritory(mode,startNormal){normalStarter=startNormal;const c=configs[mode];hideAll();screen.hidden=false;$('territoryEyebrow').textContent='território';$('territoryTitle').textContent=c.title;$('territoryIntro').textContent=c.intro;const cards=$('territoryCards');cards.textContent='';const normal=el('button','level-card');normal.type='button';normal.innerHTML=`<strong>${c.normal}</strong><span>${c.normalCopy}</span>`;normal.onclick=()=>{screen.hidden=true;normalStarter();};const end=el('button',`level-card endgame-card ${mode}`);end.type='button';end.innerHTML=`<small>ENDGAME</small><strong>${c.end}</strong><span>${c.endCopy}</span>`;end.onclick=()=>openChallenge(c.end.toLowerCase());cards.append(normal,end);}
function openChallenge(mode){hideAll();challenge.hidden=false;run={mode};$('challengeIntro').hidden=false;$('challengePlay').hidden=true;$('challengeResult').hidden=true;const data=mode==='blitz'?['hiragana · endgame','BLITZ','O tempo começa justo. A cada acerto, ele aperta. Erro ou demora encerra a run.',`Recorde: ${stats.blitz.bestStreak} · melhor média: ${stats.blitz.bestAverageMs?`${(stats.blitz.bestAverageMs/1000).toFixed(2)}s`:'—'}`]:mode==='alien'?['katakana · endgame','ALIEN','Quinze sinais. Empréstimos comuns primeiro; adaptações japonesas traiçoeiras depois.',`Precisão: ${stats.alien.hits+stats.alien.errors?Math.round(stats.alien.hits/(stats.alien.hits+stats.alien.errors)*100):0}% · melhor sequência: ${stats.alien.bestStreak}`]:['kanji · endgame','CHIMERA','As partes são conhecidas. O composto talvez não. Levante a hipótese mais forte; ambiguidades legítimas não são punidas.',`Precisão: ${stats.chimera?.hits+stats.chimera?.errors?Math.round(stats.chimera.hits/(stats.chimera.hits+stats.chimera.errors)*100):0}% · conteúdo curado`];$('challengeEyebrow').textContent=data[0];$('challengeTitle').textContent=data[1];$('challengeCopy').textContent=data[2];$('challengeRecord').textContent=data[3];$('challengeStart').onclick=startChallenge;}
function startChallenge(){clearInterval(timer);$('challengeIntro').hidden=true;$('challengeResult').hidden=true;$('challengePlay').hidden=false;$('challengeFeedback').textContent='';turn=0;streak=0;hits=0;errors=0;previous=[];const mode=run.mode;run={mode,territory:mode==='blitz'?'hiragana':mode==='alien'?'katakana':'kanji',startedAt:Date.now(),sessionId:root.KANA_PERSISTENCE.uuid(),streak:0};if(mode==='blitz'){previous=null;nextBlitz();}else if(mode==='alien')nextAlien();else{pool=core.chimeraPool(repos.mastery.getSkills());nextChimera();}cloudSession();}
function nextBlitz(){clearInterval(timer);current=core.pickDifferent(core.blitzPool(run.streak),previous);previous=current[0];const limit=core.blitzLimit(run.streak);deadline=Date.now()+limit;$('challengeMode').textContent='BLITZ';$('challengeSignal').textContent='';$('timerTrack').hidden=false;$('challengeGlyph').textContent=current[0];$('challengePrompt').textContent='Digite em rōmaji';$('challengeForm').hidden=false;$('challengeChoices').hidden=true;$('challengeAnswer').value='';$('challengeAnswer').placeholder=current[0].length>1?'sequência':'som';$('challengeAnswer').focus();questionAt=Date.now();timer=setInterval(()=>{const remaining=Math.max(0,deadline-Date.now());$('timerFill').style.width=`${remaining/limit*100}%`;if(!remaining)finishBlitz('timeout');},40);}
function submitBlitz(value){const elapsed=Date.now()-questionAt;if(Date.now()>deadline){finishBlitz('timeout');return;}if(!core.accepts(value,current[1])){finishBlitz('wrong',value);return;}clearInterval(timer);run.streak++;hits++;const s=stats.blitz.items[current[0]]||{hits:0,errors:0,totalMs:0};s.hits++;s.totalMs+=elapsed;stats.blitz.items[current[0]]=s;cloudAttempt('blitz',current,true,elapsed);cloudSession();save();nextBlitz();}
function finishBlitz(reason,given=''){clearInterval(timer);const elapsed=Date.now()-questionAt;errors++;cloudAttempt('blitz',current,false,elapsed);const done=core.finishBlitz(stats,run,reason,current);stats=done.stats;save();root.dispatchEvent(new CustomEvent('kana:run-ended',{detail:{mode:'blitz',itemId:"blitz:"+current[0],display:current[0],reading:Array.isArray(current[1])?current[1][0]:current[1],runLength:done.result.streak,answer:given||reason,at:Date.now()}}));cloudSession('completed',{reason,streak:done.result.streak,defeat:{written:current[0],given,accepted:Array.isArray(current[1])?current[1]:[current[1]]}});$('challengePlay').hidden=true;$('challengeResult').hidden=false;$('resultEyebrow').textContent=reason==='timeout'?'tempo esgotado':'resposta incorreta';$('resultNumber').textContent=done.result.streak;$('resultTitle').textContent='SÍMBOLOS CONSECUTIVOS';const slow=core.slowestBlitz(stats).map(item=>item.symbol).join(' · ');$('resultCopy').textContent=`${current[0]} era ${(Array.isArray(current[1])?current[1]:[current[1]]).join(' ou ')}${given?`. Você respondeu: ${given}`:''}. Recorde: ${stats.blitz.bestStreak}.${slow?` Mais lentos: ${slow}.`:''}`;$('challengeRetry').onclick=startChallenge;}
function nextAlien(){if(turn>=15){finishAlien();return;}const source=core.alienPool(turn);current=core.pickDifferent(source,previous);previous.push(current.id);questionAt=Date.now();renderChoiceQuestion('ALIEN',`sinal ${turn+1} / 15`,current.written,'O que isso representa?',core.alienChoices(current),submitAlien);}
function submitAlien(value,button){const correct=core.accepts(value,current.answers),elapsed=Date.now()-questionAt;stats=core.recordAlien(stats,current,correct,elapsed);cloudAttempt('alien',current,correct,elapsed);if(correct){hits++;streak++;stats.alien.bestStreak=Math.max(stats.alien.bestStreak,streak);button.classList.add('correct');$('challengeFeedback').textContent='Sinal decifrado.';}else{errors++;streak=0;button.classList.add('wrong');$('challengeFeedback').textContent=`Era ${current.answers[0]}.`;}turn++;cloudSession();save();disableChoices();setTimeout(nextAlien,correct?360:780);}
function finishAlien(){stats.alien.sessions++;save();cloudSession('completed');showResult('transmissão encerrada',`${Math.round(hits/15*100)}%`,'DECIFRADO',`${hits} sinais reconhecidos · ${errors} não identificados. Melhor sequência geral: ${stats.alien.bestStreak}.`);}
function nextChimera(){if(turn>=12){finishChimera();return;}current=pool[turn%pool.length];questionAt=Date.now();const parts=current.components.map(([kanji,meaning])=>`${kanji} ${meaning}`).join('  +  ');renderChoiceQuestion('CHIMERA',`composto ${turn+1} / 12`,current.written,`${current.reading} · ${parts}`,core.chimeraChoices(current),submitChimera);}
function submitChimera(value,button){const correct=core.accepts(value,current.answers),elapsed=Date.now()-questionAt;stats=core.recordChimera(stats,current,correct,elapsed);cloudAttempt('chimera',current,correct,elapsed);if(correct){hits++;streak++;stats.chimera.bestStreak=Math.max(stats.chimera.bestStreak,streak);button.classList.add('correct');$('challengeFeedback').textContent=current.explanation;}else{errors++;streak=0;button.classList.add('wrong');$('challengeFeedback').textContent=`Hipótese real: ${current.answers[0]}. ${current.explanation}`;}turn++;cloudSession();save();disableChoices();setTimeout(nextChimera,correct?800:1350);}
function finishChimera(){stats.chimera.sessions++;save();cloudSession('completed');showResult('inferência concluída',`${Math.round(hits/12*100)}%`,'COMPOSTOS INTERPRETADOS',`${hits} hipóteses confirmadas · ${errors} revistas. O significado real foi mostrado depois de cada composto.`);}
function renderChoiceQuestion(mode,signal,glyph,prompt,values,handler){$('challengeMode').textContent=mode;$('challengeSignal').textContent=signal;$('timerTrack').hidden=true;$('challengeGlyph').textContent=glyph;$('challengePrompt').textContent=prompt;$('challengeForm').hidden=true;const choices=$('challengeChoices');choices.hidden=false;choices.textContent='';values.forEach(value=>{const button=el('button','choice',value);button.type='button';button.onclick=()=>handler(value,button);choices.append(button);});$('challengeFeedback').textContent='';}
function disableChoices(){document.querySelectorAll('#challengeChoices button').forEach(button=>button.disabled=true);}
function showResult(eyebrow,number,title,copy){$('challengePlay').hidden=true;$('challengeResult').hidden=false;$('resultEyebrow').textContent=eyebrow;$('resultNumber').textContent=number;$('resultTitle').textContent=title;$('resultCopy').textContent=copy;$('challengeRetry').onclick=startChallenge;}
$('challengeForm').addEventListener('submit',event=>{event.preventDefault();const value=$('challengeAnswer').value.trim();if(value&&run?.mode==='blitz')submitBlitz(value);});
function handleBack(){if(screen.hidden&&challenge.hidden)return false;clearInterval(timer);if(run?.sessionId&&(hits||errors))cloudSession('completed',{abandoned:true});screen.hidden=true;challenge.hidden=true;home.hidden=false;study.hidden=false;back.hidden=true;return true;}
root.KANA_ENDGAMES={openTerritory,handleBack,getStats:()=>JSON.parse(JSON.stringify(stats))};
})(window);
